<script setup lang="ts">
import { nextTick, onMounted, onUnmounted, ref } from 'vue'
type LogLine={text:string;level:'normal'|'error'|'warn'}
const props=defineProps<{instanceId:string}>();const logs=ref<LogLine[]>([]);const command=ref('');const connected=ref(false);const sending=ref(false);const viewport=ref<HTMLElement|null>(null);let source:EventSource|null=null
function classify(text:string):LogLine['level']{if(/error|exception|failed|fatal/i.test(text))return'error';if(/warn|warning/i.test(text))return'warn';return'normal'}
function append(text:string){logs.value.push(...text.split(/\r?\n/).filter(Boolean).map(line=>({text:line,level:classify(line)})));if(logs.value.length>500)logs.value.splice(0,logs.value.length-500);nextTick(()=>{if(viewport.value)viewport.value.scrollTop=viewport.value.scrollHeight})}
function connect(){source?.close();source=new EventSource('/api/instances/'+encodeURIComponent(props.instanceId)+'/logs/stream');source.onopen=()=>connected.value=true;source.onmessage=e=>{try{const p=JSON.parse(e.data);if(p.logs)append(p.logs);if(p.line)append(p.line)}catch{append(e.data)}};source.onerror=()=>connected.value=false}
async function sendCommand(){const value=command.value.trim();if(!value||sending.value)return;sending.value=true;try{await $fetch('/api/instances/'+encodeURIComponent(props.instanceId)+'/command',{method:'POST',credentials:'include',body:{command:value}});append('> '+value);command.value=''}catch(e:any){append('[command error] '+(e?.data?.message||'指令发送失败'))}finally{sending.value=false}}
onMounted(connect);onUnmounted(()=>source?.close())
</script>
<template><section class="border border-border bg-black/80 shadow-2xl"><header class="flex items-center justify-between border-b border-border px-4 py-3 font-mono text-[10px] tracking-[0.18em]"><span class="text-text-secondary">LIVE CONSOLE / {{ instanceId }}</span><span :class="connected?'text-data-live':'text-text-secondary'">● {{ connected?'STREAM ONLINE':'CONNECTING' }}</span></header><div ref="viewport" class="h-[420px] overflow-y-auto p-4 font-mono text-xs leading-6"><p v-if="!logs.length" class="text-text-secondary">等待服务端日志……</p><p v-for="(line,index) in logs" :key="index" :class="line.level==='error'?'text-red-400':line.level==='warn'?'text-amber-300':'text-text-secondary'">{{ line.text }}</p></div><form class="flex border-t border-border" @submit.prevent="sendCommand"><span class="px-4 py-3 font-mono text-brand">&gt;</span><input v-model="command" class="min-w-0 flex-1 bg-transparent px-1 py-3 font-mono text-xs text-text-primary outline-none placeholder:text-text-secondary" placeholder="输入服务器指令，例如 say hello"><button type="submit" class="border-l border-border px-4 font-mono text-[10px] text-brand hover:bg-surface disabled:opacity-50" :disabled="sending">SEND</button></form></section></template>